export default "/* src/agent-ui/index.css */\n\n:host {\n  all: initial; \n  display: block;\n  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n  font-size: 14px;\n}\n\n.copilot-root {\n  position: relative;\n}\n\n.agent-bubble {\n  position: fixed;\n  bottom: 20px;\n  right: 20px;\n  width: 50px;\n  height: 50px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, #007bff 0%, #0056b3 100%);\n  color: white;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 20px;\n  cursor: pointer;\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n  user-select: none;\n  border: 2px solid rgba(255, 255, 255, 0.2);\n  z-index: 2147483647; /* Max z-index */\n}\n\n.agent-bubble:hover {\n  transform: scale(1.05);\n  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);\n}\n\n.agent-bubble.danger {\n  background: linear-gradient(135deg, #ff4d4d 0%, #b30000 100%);\n  animation: pulse 2s infinite;\n}\n\n.chat-container {\n  position: fixed;\n  bottom: 80px;\n  right: 20px;\n  width: 450px; /* Increased from 350px */\n  height: 650px; /* Increased from 500px */\n  background: #ffffff;\n  border-radius: 16px;\n  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  border: 1px solid #e1e4e8;\n  animation: slideIn 0.3s ease-out;\n  z-index: 2147483647;\n}\n\n/* 4. Chat Header */\n.chat-header {\n  padding: 16px;\n  background: #007bff; /* Copilot blue */\n  color: white;\n  font-weight: 600;\n  font-size: 15px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  box-shadow: 0 2px 5px rgba(0,0,0,0.1);\n  z-index: 2;\n}\n\n/* 5. Message List (Scrollable Area) */\n.message-list {\n  flex: 1;\n  padding: 16px;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  background: #f8f9fa;\n}\n\n/* 6. Individual Chat Bubbles */\n.message-bubble {\n  max-width: 90%;\n  padding: 12px 18px;\n  border-radius: 18px;\n  font-size: 14.5px; /* Slightly larger font */\n  line-height: 1.5;\n  word-wrap: break-word;\n}\n\n.message-bubble p { margin: 0 0 8px 0; }\n.message-bubble p:last-child { margin: 0; }\n.message-bubble pre { background: #f0f0f0; padding: 8px; border-radius: 6px; overflow-x: auto; }\n.message-bubble code { background: rgba(0,0,0,0.05); padding: 2px 4px; border-radius: 4px; font-family: monospace; }\n.message-bubble ul, .message-bubble ol { margin: 8px 0; padding-left: 20px; }\n\n.message-bubble.bot {\n  align-self: flex-start;\n  background: #ffffff;\n  border: 1px solid #e1e4e8;\n  color: #24292e;\n  border-bottom-left-radius: 4px;\n}\n\n.message-bubble.bot:has(span:contains('🚨')), \n.message-bubble.bot[data-threat=\"true\"] { /* Fallback or alternative logic */\n  border-left: 4px solid #ff4d4d;\n  background: #fff5f5;\n}\n\n.message-bubble.user {\n  align-self: flex-end;\n  background: #007bff;\n  color: white;\n  border-bottom-right-radius: 4px;\n}\n\n/* 7. Input Area */\n.chat-input-area {\n  padding: 12px 16px;\n  background: #ffffff;\n  border-top: 1px solid #e1e4e8;\n  display: flex;\n  gap: 10px;\n  align-items: center;\n}\n\n.chat-input-area input {\n  flex: 1;\n  padding: 10px 14px;\n  border: 1px solid #d1d5da;\n  border-radius: 20px;\n  outline: none;\n  font-size: 14px;\n  transition: border-color 0.2s ease;\n  font-family: inherit;\n}\n\n.chat-input-area input:focus {\n  border-color: #007bff;\n}\n\n.chat-input-area input:disabled {\n  background: #f6f8fa;\n  cursor: not-allowed;\n}\n\n@keyframes pulse {\n  0% { box-shadow: 0 0 0 0 rgba(255, 77, 77, 0.7); }\n  70% { box-shadow: 0 0 0 12px rgba(255, 77, 77, 0); }\n  100% { box-shadow: 0 0 0 0 rgba(255, 77, 77, 0); }\n}\n\n@keyframes slideIn {\n  from { opacity: 0; transform: translateY(20px) scale(0.98); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n\n.message-list::-webkit-scrollbar {\n  width: 6px;\n}\n\n.message-list::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n.message-list::-webkit-scrollbar-thumb {\n  background-color: #c1c1c1;\n  border-radius: 10px;\n}\n\n"